INSERT INTO users (id, name, email, password, profile_image, bio, country, fav_cuisine, cover_image) VALUES
(1, 'Chef Gordon Ramsay', 'gordon@example.com', '$2b$10$FQVUsftdVBZZOCnC/aFFs.1pLXgjehX6jCiWlP1CG29BP9wbyOWDi', 'https://images.unsplash.com/photo-1577219491135-ce391730fb2c?auto=format&fit=crop&w=400&q=80', 'Master Chef passionate about authentic Mediterranean & Italian cuisine. 30+ years of culinary experience.', 'United Kingdom', 'Italian', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=80'),
(2, 'Maria Rodriguez', 'maria@example.com', '$2b$10$FQVUsftdVBZZOCnC/aFFs.1pLXgjehX6jCiWlP1CG29BP9wbyOWDi', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&q=80', 'Foodie, home cook & pastry enthusiast. Crafting healthy & delicious everyday meals.', 'Spain', 'Pastry & Dessert', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80'),
(3, 'Kenji Takahashi', 'kenji@example.com', '$2b$10$FQVUsftdVBZZOCnC/aFFs.1pLXgjehX6jCiWlP1CG29BP9wbyOWDi', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'Ramen master & Japanese street food explorer. Sharing traditional recipes with a modern twist.', 'Japan', 'Japanese', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=1200&q=80'),
(4, 'Chef Lakshmi Venkatesh', 'lakshmi@example.com', '$2b$10$FQVUsftdVBZZOCnC/aFFs.1pLXgjehX6jCiWlP1CG29BP9wbyOWDi', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=400&q=80', 'South Indian culinary master preserving traditional Tamil, Keralite, and Andhra flavors passed down over generations.', 'India', 'South Indian', 'https://images.unsplash.com/photo-1610192244261-3f33de3f55e4?auto=format&fit=crop&w=1200&q=80');
INSERT INTO recipes (id, user_id, title, description, ingredients, instructions, prep_time, cook_time, servings, category, difficulty, cuisine, calories, image, views_count) VALUES
(1, 1, 'Creamy Tuscan Garlic Chicken', 'Tender chicken breasts simmered in a rich garlic, sun-dried tomato, and spinach cream sauce.', '4 chicken breasts\n2 tbsp olive oil\n1 cup heavy cream\n1/2 cup chicken broth\n1 tsp garlic powder\n1 cup spinach\n1/2 cup sun-dried tomatoes\n1/2 cup parmesan cheese', '1. Season chicken breasts with salt, pepper, and garlic powder.\n2. Heat olive oil in skillet and sear chicken for 6-8 mins per side.\n3. Add garlic, sun-dried tomatoes, and chicken broth.\n4. Pour in heavy cream and parmesan cheese, stirring until smooth.\n5. Add spinach and return chicken to pan. Simmer for 3 mins.', 15, 25, 4, 'Dinner', 'Medium', 'Italian', 480, 'http://localhost:5000/uploads/perfect_food_1.jpg', 142),
(2, 2, 'Avocado Toast with Poached Egg', 'Artisanal sourdough topped with creamy smashed avocado, chili flakes, and perfectly poached egg.', '2 slices sourdough bread\n1 ripe avocado\n2 fresh eggs\n1 tbsp lemon juice\n1/2 tsp red pepper flakes\nSalt and black pepper to taste', '1. Toast sourdough slices until golden brown.\n2. Mash avocado with lemon juice, salt, and black pepper.\n3. Poach eggs in simmering water with vinegar for 3 mins.\n4. Spread mashed avocado generously over toast.\n5. Top with poached egg and chili flakes.', 10, 10, 2, 'Breakfast', 'Easy', 'American', 320, 'http://localhost:5000/uploads/perfect_food_2.jpg', 98),
(3, 3, 'Authentic Shoyu Ramen Bowl', 'Rich, savory soy-sauce based dashi broth loaded with chewy ramen noodles, tender chashu pork, ajitsuke tamago egg, and scallions.', '2 packs fresh ramen noodles\n4 cups chicken/dashi stock\n3 tbsp shoyu (soy sauce)\n1 tbsp mirin\n1 tsp sesame oil\n4 slices chashu pork\n2 soft-boiled marinated eggs\nChopped scallions & nori sheets', '1. Combine chicken stock, shoyu, mirin, and sesame oil in saucepan.\n2. Cook ramen noodles for 2 mins and drain.\n3. Divide noodles into deep serving bowls.\n4. Pour boiling shoyu broth over noodles.\n5. Top neatly with chashu pork, halved soft-boiled egg, and nori sheets.', 20, 40, 2, 'Lunch', 'Hard', 'Japanese', 550, 'http://localhost:5000/uploads/perfect_food_3.jpg', 215),
(4, 4, 'Crispy Masala Dosa with Sambar & Coconut Chutney', 'Authentic South Indian fermented rice and black gram crepe stuffed with aromatic spiced potato masala, served with vegetable sambar.', '3 cups parboiled rice\n1 cup urad dal (black gram)\n1/2 tsp fenugreek seeds\n4 boiled potatoes\n1 mustard seeds, curry leaves, turmeric\n2 green chilies chopped\nSalt to taste', '1. Soak rice and urad dal for 6 hours; grind into smooth batter and ferment overnight.\n2. Heat a tawa or cast iron skillet and pour a ladle of batter; spread in thin concentric circles.\n3. Drizzle ghee along edges until golden and crispy.\n4. Place spiced potato masala in the center and fold.\n5. Serve piping hot with coconut chutney and sambar!', 30, 20, 4, 'Breakfast', 'Medium', 'South Indian', 380, 'http://localhost:5000/uploads/perfect_food_4.jpg', 310),
(5, 4, 'Hyderabadi Chicken Dum Biryani', 'Royal Nizam recipe featuring fragrant basmati rice dum-cooked with marinated chicken, saffron, caramelized onions, mint, and whole spices.', '1 kg chicken cut in pieces\n3 cups long-grain Basmati rice\n1 cup thick curd (yogurt)\n2 tbsp ginger-garlic paste\n1 cup fried onions (birista)\nWhole spices (cardamom, cloves, cinnamon, star anise)\nSaffron milk & ghee', '1. Marinate chicken with curd, ginger-garlic paste, biryani masala, mint, and fried onions for 2 hours.\n2. Parboil basmati rice with whole spices until 70% cooked.\n3. Layer marinated chicken at the bottom of heavy vessel, top with rice, ghee, and saffron milk.\n4. Seal tightly with dough foil and dum cook on low flame for 35 mins.\n5. Gently mix layers and serve with cucumber onion raita!', 40, 45, 6, 'Dinner', 'Hard', 'South Indian', 620, 'http://localhost:5000/uploads/perfect_food_5.jpg', 480),
(6, 4, 'Chettinad Spicy Chicken Curry', 'Fiery Tamil Nadu chicken curry seasoned with freshly roasted star anise, dried red chilies, poppy seeds, and coconut.', '800g chicken pieces\n2 tbsp Chettinad masala powder\n1 cup chopped onions\n2 tomatoes pureed\n1/2 cup fresh grated coconut\nCurry leaves & ginger garlic paste', '1. Dry roast whole spices with coconut and grind to smooth masala paste.\n2. Saute onions, curry leaves, and ginger garlic paste in oil until deep golden.\n3. Add chicken pieces and sear for 5 mins.\n4. Stir in Chettinad spice paste, tomato puree, and water. Simmer covered for 25 mins.\n5. Garnish with fresh coriander and serve with steamed rice or parotta!', 20, 30, 4, 'Dinner', 'Medium', 'South Indian', 440, 'http://localhost:5000/uploads/perfect_food_6.jpg', 185),
(7, 4, 'Fluffy Steamed Idli with Vegetable Sambar', 'Soft, pillowy steamed rice cakes served with aromatic toor dal lentil vegetable sambar and tangy tomato chutney.', '3 cups idli rice\n1 cup urad dal\n1 cup toor dal for sambar\nAssorted vegetables (drumstick, carrots, pumpkin)\n1 tbsp sambar powder & tamarind pulp', '1. Prepare fermented idli batter and pour into greased idli molds.\n2. Steam in idli cooker for 10-12 mins until tooth pick comes out clean.\n3. Pressure cook toor dal with vegetables, tamarind, and sambar powder for sambar.\n4. Temper sambar with mustard seeds, dried red chilies, and curry leaves.\n5. Serve warm soft idlis immersed in hot sambar!', 20, 15, 4, 'Breakfast', 'Easy', 'South Indian', 260, 'http://localhost:5000/uploads/perfect_food_7.jpg', 230),
(8, 4, 'Crispy South Indian Medu Vada', 'Golden, doughnut-shaped crispy fritters made from spiced black gram batter with crushed black pepper, ginger, and curry leaves.', '2 cups urad dal (soaked 4 hours)\n1 tbsp crushed black pepper\n1 tbsp finely chopped ginger\n10 curry leaves chopped\n2 green chilies chopped\nOil for deep frying', '1. Grind soaked urad dal with minimal water into fluffy batter.\n2. Add black pepper, ginger, curry leaves, green chilies, and salt; mix vigorously.\n3. Wet palms, shape dough ball into doughnut form with center hole.\n4. Slide carefully into hot oil and fry until golden brown and crispy.\n5. Serve immediately with coconut chutney and sambar!', 15, 20, 4, 'Starter', 'Medium', 'South Indian', 310, 'http://localhost:5000/uploads/perfect_food_8.jpg', 275),
(9, 2, 'Classic Italian Tiramisu', 'Indulgent coffee-flavored Italian dessert with layers of cocoa-dusted mascarpone cream and espresso-soaked ladyfingers.', '24 savoiardi ladyfingers\n1 cup strong espresso coffee\n2 tbsp dark rum or coffee liqueur\n3 large egg yolks\n1/2 cup sugar\n250g mascarpone cheese\n1 cup heavy whipping cream\nUnsweetened cocoa powder for dusting', '1. Whisk egg yolks and sugar over double boiler until pale and creamy.\n2. Fold mascarpone cheese into yolk mixture until velvety smooth.\n3. Whip heavy cream to stiff peaks and gently fold into mascarpone cream.\n4. Mix espresso and rum; dip ladyfingers briefly and layer in dish.\n5. Spread half the cream, add another layer of ladyfingers, top with remaining cream.\n6. Dust generously with cocoa powder and chill for 6 hours.', 25, 0, 6, 'Dessert', 'Medium', 'Italian', 420, 'http://localhost:5000/uploads/perfect_food_9.jpg', 165),
(10, 2, 'Saffron Mango Kulfi with Pistachios', 'Traditional dense Indian frozen ice cream flavored with sweet Alphonso mangoes, cardamoms, saffron strands, and slivered pistachios.', '2 cups sweet mango pulp\n2 cups full-fat milk\n1 cup condensed milk\n1/2 cup heavy cream\n1/4 tsp cardamom powder\n10 saffron strands soaked in warm milk\n2 tbsp chopped pistachios and almonds', '1. Simmer full-fat milk in heavy saucepan until reduced to half volume.\n2. Stir in condensed milk, saffron milk, and cardamom powder; cool completely.\n3. Blend reduced milk with mango pulp and heavy cream until silky.\n4. Pour into traditional kulfi molds and sprinkle crushed pistachios on top.\n5. Freeze overnight for at least 8 hours; unmold and serve chilled.', 20, 25, 4, 'Dessert', 'Easy', 'Indian', 280, 'http://localhost:5000/uploads/perfect_food_10.jpg', 190),
(11, 2, 'Refreshing Mango Lassi', 'Creamy, sweet Indian yogurt drink blended with ripe Alphonso mangoes, cardamom, and rose water.', '2 cups fresh ripe mango chunks\n1.5 cups chilled thick yogurt (curd)\n1/2 cup milk or ice cubes\n3 tbsp honey or sugar\n1/4 tsp ground cardamom\nDash of rose water & saffron for garnish', '1. Add mango chunks, yogurt, milk, sugar, and cardamom to blender.\n2. Blend on high speed for 1-2 minutes until completely smooth and frothy.\n3. Adjust sweetness and thickness with milk if desired.\n4. Pour into chilled tall glasses.\n5. Garnish with saffron threads, crushed pistachios, and mint sprigs.', 10, 0, 2, 'Beverages', 'Easy', 'Indian', 210, 'http://localhost:5000/uploads/perfect_food_11.jpg', 210),
(12, 3, 'Iced Matcha Green Tea Latte', 'Vibrant Japanese ceremonial green tea whisked with warm water and poured over ice with creamy oat milk.', '1.5 tsp ceremonial grade Japanese matcha powder\n2 tbsp warm water (175°F)\n1 cup oat milk or whole milk\n1 tbsp maple syrup or honey\nIce cubes', '1. Sift matcha powder into a small bowl to remove lumps.\n2. Add warm water and whisk vigorously in a zig-zag motion with bamboo whisk until frothy.\n3. Stir in maple syrup to sweeten.\n4. Fill a glass with ice cubes and pour in oat milk.\n5. Slowly pour whisked green matcha over top to create beautiful layered effect.', 5, 0, 1, 'Beverages', 'Easy', 'Japanese', 150, 'http://localhost:5000/uploads/perfect_food_12.jpg', 175),
(13, 1, 'Fresh Mediterranean Greek Salad', 'Crispy cucumbers, juicy tomatoes, kalamata olives, red onion, and creamy feta cheese dressed with extra virgin olive oil and oregano.', '3 ripe tomatoes diced\n1 English cucumber sliced\n1 red onion thinly sliced\n1/2 cup Kalamata olives\n200g Greek feta cheese block\n1/4 cup extra virgin olive oil\n1 tbsp red wine vinegar\n1 tsp dried oregano', '1. Combine diced tomatoes, sliced cucumber, red onion, and Kalamata olives in a large salad bowl.\n2. Whisk extra virgin olive oil, red wine vinegar, dried oregano, salt, and pepper in a cup.\n3. Pour dressing over salad vegetables and gently toss.\n4. Place a thick block of creamy feta cheese right on top.\n5. Drizzle feta with olive oil and sprinkle extra oregano before serving.', 15, 0, 4, 'Salad', 'Easy', 'Mediterranean', 290, 'http://localhost:5000/uploads/perfect_food_13.jpg', 130),
(14, 2, 'Thai Peanut Noodle Salad', 'Colorful shredded purple cabbage, carrots, bell peppers, and rice noodles tossed in a creamy spicy peanut dressing.', '200g thin rice noodles\n1 cup purple cabbage shredded\n1 cup shredded carrots\n1 red bell pepper julienned\n1/2 cup edamame beans\n1/3 cup creamy peanut butter\n2 tbsp soy sauce\n1 tbsp lime juice & 1 tbsp chili garlic sauce\nFresh cilantro & crushed peanuts', '1. Cook rice noodles according to package instructions, drain, and rinse under cold water.\n2. In a bowl, whisk peanut butter, soy sauce, lime juice, chili garlic sauce, and warm water.\n3. Combine cold noodles, purple cabbage, carrots, bell pepper, and edamame in salad bowl.\n4. Pour spicy peanut dressing over salad and toss thoroughly.\n5. Top with cilantro, sesame seeds, and crushed roasted peanuts.', 20, 5, 3, 'Salad', 'Easy', 'Asian', 340, 'http://localhost:5000/uploads/perfect_food_14.jpg', 115),
(15, 1, 'Classic French Onion Soup', 'Rich caramelized onion beef broth topped with toasted baguette slices and melted Gruyere cheese.', '4 large yellow onions sliced\n3 tbsp butter\n1 tbsp olive oil\n1 tsp sugar\n4 cups rich beef broth\n1/2 cup dry white wine\n2 sprigs fresh thyme\n4 baguette slices\n1.5 cups shredded Gruyère cheese', '1. Melt butter with olive oil in Dutch oven over medium-low heat; add onions.\n2. Cook onions slowly for 45 mins, stirring occasionally until deep golden caramelized.\n3. Add white wine to deglaze pot, then pour in beef broth and fresh thyme.\n4. Simmer soup covered for 20 minutes.\n5. Ladle hot soup into oven-safe bowls, place baguette slice on top, cover with Gruyère.\n6. Broil in oven for 3-4 mins until cheese is bubbly and golden brown.', 25, 55, 4, 'Soup', 'Medium', 'French', 360, 'http://localhost:5000/uploads/perfect_food_15.jpg', 180),
(16, 2, 'Creamy Roasted Tomato Basil Soup', 'Oven-roasted plum tomatoes and garlic simmered with fresh basil and cream, served with grilled cheese.', '1.5 kg ripe plum tomatoes halved\n1 bulb garlic top sliced off\n2 tbsp olive oil\n1 onion chopped\n3 cups vegetable broth\n1/2 cup heavy cream\n1 cup fresh basil leaves', '1. Toss tomatoes and garlic bulb with olive oil, salt, pepper; roast at 400°F for 40 mins.\n2. Sauté chopped onion in pot until translucent.\n3. Squeeze roasted garlic cloves into pot, add roasted tomatoes, basil, and broth.\n4. Simmer for 15 mins then blend with immersion blender until silky smooth.\n5. Stir in heavy cream and garnish with fresh basil leaves.', 15, 45, 4, 'Soup', 'Easy', 'American', 240, 'http://localhost:5000/uploads/perfect_food_16.jpg', 205),
(17, 4, 'Mumbai Pav Bhaji with Butter Toast', 'Iconic Mumbai street food featuring a spicy mashed vegetable gravy served with buttery pan-toasted pav bread rolls.', '4 boiled potatoes\n1 cup cauliflower florets\n1/2 cup green peas\n2 onions finely chopped\n3 tomatoes chopped\n2 tbsp Pav Bhaji masala\n1 tbsp butter + extra for toast\nFresh cilantro & lemon wedges', '1. Boil potatoes, cauliflower, and peas; mash smoothly.\n2. Melt butter on flat tava or pan; sauté onions and ginger garlic paste.\n3. Add tomatoes, capsicum, and pav bhaji masala; cook until oil separates.\n4. Mix in mashed vegetables, water, and butter; simmer while mashing on tava for 15 mins.\n5. Slit pav buns, toast generously with butter on tawa, serve piping hot with bhaji!', 20, 30, 4, 'Street Food', 'Medium', 'Indian', 490, 'http://localhost:5000/uploads/perfect_food_17.jpg', 290),
(18, 2, 'Crispy Mexican Street Corn (Elote)', 'Grilled sweet corn on the cob charred over open flame, brushed with cotija mayo, chili powder, and fresh lime.', '4 ears fresh sweet corn husked\n1/4 cup cotija cheese or feta crumbled\n3 tbsp mayonnaise\n2 tbsp sour cream or Mexican crema\n1 tsp chili powder or cayenne\n1/4 cup chopped cilantro\nLime wedges', '1. Grill corn ears over high direct heat for 10-12 mins, turning until charred all around.\n2. Mix mayonnaise, sour cream, garlic powder, and lime juice in small bowl.\n3. Brush hot charred corn generously with mayo mixture.\n4. Sprinkle crumbled cotija cheese, chili powder, and cilantro all over.\n5. Serve immediately with fresh lime wedges.', 10, 12, 4, 'Street Food', 'Easy', 'Mexican', 230, 'http://localhost:5000/uploads/perfect_food_18.jpg', 160),
(19, 2, 'Creamy Chickpea Coconut Curry', 'Hearty plant-based vegan curry with tender chickpeas, spinach, and fire-roasted tomatoes simmered in coconut milk.', '2 cans (15oz) chickpeas drained\n1 can (14oz) coconut milk\n1 can diced tomatoes\n1 onion chopped\n3 cloves garlic minced\n1 tbsp curry powder & 1 tsp garam masala\n2 cups fresh baby spinach\nCooked jasmine or basmati rice', '1. Heat coconut oil in deep skillet; sauté onion, garlic, and ginger for 5 mins.\n2. Stir in curry powder, cumin, turmeric, and garam masala for 1 min.\n3. Add drained chickpeas, diced tomatoes, and coconut milk; bring to gentle boil.\n4. Simmer uncovered for 20 mins until gravy thickens.\n5. Stir in baby spinach until wilted. Serve over hot steamy basmati rice.', 10, 25, 4, 'Vegan', 'Easy', 'Indian', 390, 'http://localhost:5000/uploads/perfect_food_19.jpg', 225),
(20, 4, 'Paneer Butter Masala with Garlic Naan', 'Rich North Indian restaurant favorite with soft cottage cheese cubes simmered in a velvet tomato, butter, and cashew cream sauce.', '400g paneer cubes\n4 ripe tomatoes pureed\n1/2 cup raw cashews soaked & blended\n2 tbsp butter & 1 tbsp oil\n1 tbsp kasuri methi (dried fenugreek leaves)\n1/2 cup heavy cream\nWhole spices (bay leaf, cinnamon, cardamom)\nFresh garlic naan for serving', '1. Sauté bay leaf, cinnamon, and ginger garlic paste in butter.\n2. Add tomato puree and cook until butter separates from sides.\n3. Pour in smooth cashew paste, Kashmiri chili powder, and garam masala with water.\n4. Add paneer cubes and simmer gently for 7 mins.\n5. Finish with heavy cream and crushed kasuri methi. Serve with warm garlic naan.', 20, 25, 4, 'Vegetarian', 'Medium', 'Indian', 520, 'http://localhost:5000/uploads/perfect_food_20.jpg', 340),
(21, 1, 'Classic Woodfired Margherita Pizza', 'Authentic Neapolitan pizza topped with San Marzano tomato sauce, fresh mozzarella fior di latte, and basil leaves.', '300g Neapolitan pizza dough\n1/2 cup San Marzano tomato sauce\n150g fresh mozzarella sliced\nHandful fresh basil leaves\n2 tbsp extra virgin olive oil', '1. Stretch pizza dough into 12-inch round with raised crust edges.\n2. Spread tomato sauce evenly leaving crust border.\n3. Top with fresh mozzarella slices and basil leaves.\n4. Bake in preheated oven at 500°F (or pizza oven) for 7-10 mins until golden and bubbly.\n5. Drizzle extra virgin olive oil before slicing!', 15, 10, 3, 'Dinner', 'Easy', 'Italian', 460, 'http://localhost:5000/uploads/perfect_food_21.jpg', 195),
(22, 3, 'Crispy Japanese Pork Gyoza Dumplings', 'Pan-fried and steamed Japanese dumplings stuffed with seasoned minced pork, cabbage, ginger, and scallions.', '30 gyoza wrappers\n250g minced pork\n1 cup finely shredded napa cabbage\n2 scallions chopped\n1 tbsp ginger minced\n1 tbsp soy sauce & sesame oil', '1. Combine minced pork, cabbage, scallions, ginger, soy sauce, and sesame oil.\n2. Place 1 tbsp filling in center of wrapper; wet edges and pleat to seal tightly.\n3. Sear bottom of gyozas in oiled pan for 2 mins until golden.\n4. Pour 1/4 cup water into pan, cover immediately and steam for 4 mins.\n5. Remove lid and let remaining water evaporate until bottoms turn extra crispy. Serve with ponzu dip!', 25, 12, 4, 'Snacks', 'Medium', 'Japanese', 330, 'http://localhost:5000/uploads/perfect_food_22.jpg', 210),
(23, 2, 'Authentic Mexican Guacamole & Chips', 'Freshly smashed Hass avocados mixed with lime juice, diced tomatoes, red onions, jalapenos, and cilantro.', '3 ripe Hass avocados\n1 lime juiced\n1/2 cup red onion finely diced\n1 Roma tomato seeded & diced\n1 jalapeno pepper seeded & minced\n1/2 cup fresh cilantro chopped\nCorn tortilla chips for dipping', '1. Halve and pit avocados; scoop flesh into large bowl or molcajete.\n2. Mash coarsely with fork leaving slight chunky texture.\n3. Immediately fold in lime juice, red onion, diced tomato, jalapeno, and cilantro.\n4. Season with sea salt to taste.\n5. Serve immediately with warm crispy corn tortilla chips!', 10, 0, 4, 'Snacks', 'Easy', 'Mexican', 280, 'http://localhost:5000/uploads/perfect_food_23.jpg', 140),
(24, 2, 'Superfood Wild Berry Acai Smoothie Bowl', 'Thick blended acai berry smoothie topped with sliced bananas, chia seeds, toasted coconut flakes, and granolas.', '2 frozen acai berry packs\n1 cup frozen wild blueberries & strawberries\n1 ripe banana\n1/2 cup almond milk\nToppings: sliced banana, chia seeds, granola, coconut flakes', '1. Add frozen acai packs, wild berries, banana, and almond milk to high-speed blender.\n2. Blend on low speed using tamper until thick and sorbet-like.\n3. Scoop smoothie into chilled serving bowl.\n4. Arrange sliced bananas, crunchy granola, chia seeds, and coconut flakes in neat rows.\n5. Serve immediately with spoon!', 10, 0, 2, 'Breakfast', 'Easy', 'Global', 250, 'http://localhost:5000/uploads/perfect_food_24.jpg', 160),
(25, 3, 'Authentic Pad Thai Noodles with Tofu', 'Classic Thai stir-fried flat rice noodles with crispy tofu, bean sprouts, crushed peanuts, tamarind, and lime.', '200g rice noodles\n150g firm tofu diced\n2 cups bean sprouts\n3 tbsp tamarind paste\n2 tbsp fish sauce or soy sauce\n1 tbsp palm sugar\nCrushed peanuts & lime wedges', '1. Soak rice noodles in warm water for 20 mins until pliable.\n2. Stir fry diced tofu in wok until golden brown.\n3. Add tamarind paste, soy sauce, and palm sugar; toss in drained rice noodles.\n4. Stir in bean sprouts and green onions for 1 minute.\n5. Serve piping hot garnished with roasted crushed peanuts and lime wedges!', 15, 10, 2, 'Lunch', 'Medium', 'Thai', 420, 'http://localhost:5000/uploads/perfect_food_25.jpg', 175),
(26, 2, 'Traditional Spanish Seafood Paella', 'Vibrant saffron rice loaded with jumbo shrimp, calamari, mussels, sweet bell peppers, and green peas.', '2 cups Bomba paella rice\n4 cups seafood stock\n1/2 tsp saffron strands\n200g jumbo shrimp\n200g mussels cleaned\n150g calamari rings\n1 red bell pepper & peas', '1. Heat olive oil in large paella pan; sauté bell peppers and garlic.\n2. Add Bomba rice and coat in oil for 2 mins.\n3. Pour in saffron-infused warm seafood stock; bring to simmer without stirring.\n4. Arrange shrimp, calamari, and mussels on top of rice during last 8 mins.\n5. Let rest off heat for 5 mins to build socarrat crust on bottom.', 20, 35, 4, 'Dinner', 'Hard', 'Spanish', 530, 'http://localhost:5000/uploads/perfect_food_26.jpg', 220),
(27, 2, 'Classic French Croissant with Butter & Jam', 'Golden flaky layer pastry crafted with French butter, served warm with apricot preserve.', '250g croissant dough\n150g European butter for laminating\n1 egg for egg wash\nFruit jam for serving', '1. Laminate dough with butter by folding 3 times and chilling between turns.\n2. Roll out and cut into long triangles; roll up tightly into crescent shapes.\n3. Proof croissants for 2 hours until pillowy and jiggly.\n4. Brush with egg wash and bake at 390°F for 18 mins until deep golden.\n5. Serve warm with French butter and jam!', 45, 20, 6, 'Breakfast', 'Hard', 'French', 340, 'http://localhost:5000/uploads/perfect_food_27.jpg', 190),
(28, 3, 'Crispy Vegetable Spring Rolls', 'Golden fried spring rolls stuffed with glass noodles, shredded cabbage, carrots, and wood ear mushrooms.', '12 spring roll wrappers\n1 cup shredded cabbage\n1/2 cup grated carrots\n50g glass noodles cooked\n1 tbsp soy sauce & sesame oil\nOil for deep frying', '1. Sauté cabbage, carrots, and glass noodles with soy sauce for 2 mins; cool.\n2. Place 2 tbsp filling on wrapper corner, roll tightly, fold sides, and seal tip with cornstarch paste.\n3. Heat oil to 350°F.\n4. Fry spring rolls in batches for 4-5 mins until crispy and golden.\n5. Drain on paper towels and serve with sweet chili dip!', 20, 15, 4, 'Snacks', 'Easy', 'Chinese', 290, 'http://localhost:5000/uploads/perfect_food_28.jpg', 160),
(29, 4, 'Authentic Indian Butter Chicken (Murgh Makhani)', 'Tender chicken marinated in yogurt & spices simmered in a velvety cream, butter, and tomato gravy.', '800g boneless chicken thigh\n1/2 cup yogurt\n2 tbsp ginger-garlic paste\n3 tbsp butter & 1/2 cup heavy cream\n2 cups tomato puree\n1 tbsp kasuri methi & garam masala', '1. Marinate chicken with yogurt, ginger-garlic paste, and spices for 2 hours.\n2. Sear chicken pieces in hot pan until charred.\n3. Prepare velvety gravy by cooking tomato puree with butter, cashew paste, and spices.\n4. Add chicken to gravy and simmer for 10 mins.\n5. Stir in heavy cream and crushed kasuri methi before serving with rice or naan.', 25, 25, 4, 'Dinner', 'Medium', 'Indian', 560, 'http://localhost:5000/uploads/perfect_food_29.jpg', 310),
(30, 2, 'Gluten-Free Quinoa Power Bowl', 'Nutritious quinoa topped with roasted sweet potatoes, avocado slices, chickpeas, pumpkin seeds, and tahini dressing.', '1 cup cooked quinoa\n1 roasted sweet potato cubed\n1/2 avocado sliced\n1/2 cup canned chickpeas\n2 tbsp pumpkin seeds\n2 tbsp lemon tahini dressing', '1. Cook quinoa according to package instructions and cool slightly.\n2. Roast sweet potato cubes in oven with olive oil and cumin at 400°F for 25 mins.\n3. Arrange quinoa in serving bowl.\n4. Top neatly with roasted sweet potato, chickpea, avocado, and pumpkin seeds.\n5. Drizzle creamy lemon tahini dressing right before enjoying!', 15, 25, 2, 'Salad', 'Easy', 'Global', 360, 'http://localhost:5000/uploads/perfect_food_30.jpg', 145),
(31, 4, 'Traditional South Indian Sambar Rice (Bisibelebath)', 'Karnataka comfort dish of rice, lentils, and mixed vegetables cooked together with ghee, spices, and tamarind.', '1 cup rice\n1/2 cup toor dal\n1 cup mixed veggies (carrots, beans, peas)\n2 tbsp Bisibelebath powder\n1 tbsp tamarind pulp\n2 tbsp ghee & cashews', '1. Pressure cook rice, toor dal, and chopped vegetables with water for 4 whistles.\n2. Heat ghee in pan; fry cashews, mustard seeds, and curry leaves.\n3. Stir tamarind pulp and Bisibelebath spice powder into cooked rice-dal mixture.\n4. Simmer for 10 mins adding water to reach porridge consistency.\n5. Pour fried ghee cashews on top and serve hot with potato chips!', 20, 25, 4, 'Lunch', 'Medium', 'South Indian', 410, 'http://localhost:5000/uploads/perfect_food_31.jpg', 180),
(32, 2, 'Decadent Chocolate Lava Cake', 'Rich dark chocolate cake with a warm, gooey molten chocolate center, served with vanilla bean ice cream.', '100g dark chocolate 70%\n1/2 cup unsalted butter\n2 eggs + 2 egg yolks\n1/4 cup sugar\n2 tbsp flour\nVanilla ice cream for serving', '1. Melt dark chocolate and butter over double boiler.\n2. Whisk eggs, yolks, and sugar until pale and fluffy.\n3. Gently fold melted chocolate and flour into egg mixture.\n4. Pour into greased and cocoa-dusted ramekins.\n5. Bake at 425°F for exactly 12 mins. Invert onto plate and serve immediately with ice cream!', 15, 12, 4, 'Dessert', 'Medium', 'French', 480, 'http://localhost:5000/uploads/perfect_food_32.jpg', 240),
(33, 2, 'Authentic Mexican Birria Quesatacos', 'Crispy corn tortillas dipped in rich birria broth, filled with braised shredded beef and melted Oaxaca cheese.', '500g braised beef chuck shredded\n8 corn tortillas\n2 cups shredded Oaxaca cheese\n2 cups rich birria consommé\nChopped cilantro & onions', '1. Dip corn tortillas into top oil layer of warm birria consommé.\n2. Place tortilla on hot griddle; sprinkle Oaxaca cheese and braised shredded beef.\n3. Fold into taco and fry until golden crispy on both sides.\n4. Serve hot alongside a bowl of warm consommé for dipping, garnished with cilantro and onion!', 30, 40, 4, 'Street Food', 'Hard', 'Mexican', 580, 'http://localhost:5000/uploads/perfect_food_33.jpg', 290),
(34, 2, 'Cold Brew Iced Coffee with Vanilla Foam', 'Smooth 16-hour steep cold brew coffee poured over ice and crowned with sweet vanilla cold cream foam.', '1 cup cold brew coffee concentrate\n1/2 cup water or milk\nIce cubes\n3 tbsp heavy cream\n1 tbsp milk & 1 tsp vanilla syrup', '1. Steep coarse coffee grounds in cold water for 16 hours; strain cold brew concentrate.\n2. In a small cup, froth heavy cream, milk, and vanilla syrup until thick sweet foam forms.\n3. Fill tall glass with ice cubes and pour cold brew over ice.\n4. Spoon sweet vanilla cold foam over top.\n5. Serve with straw!', 5, 0, 1, 'Beverages', 'Easy', 'American', 140, 'http://localhost:5000/uploads/perfect_food_34.jpg', 165),
(35, 1, 'Creamy Wild Mushroom Risotto', 'Arborio rice slowly simmered in rich vegetable broth with sautéed cremini, shiitake mushrooms, and parmesan.', '1.5 cups Arborio rice\n4 cups warm vegetable stock\n250g mixed mushrooms sliced\n1/2 cup dry white wine\n1/2 cup parmesan cheese\n2 tbsp butter & olive oil', '1. Sauté sliced mushrooms in butter until golden; set aside.\n2. Sauté minced shallots and Arborio rice in olive oil for 2 mins.\n3. Deglaze with white wine until absorbed.\n4. Add warm stock one ladle at a time, stirring constantly until rice is creamy and al dente.\n5. Stir in sautéed mushrooms, butter, and parmesan cheese!', 15, 30, 4, 'Dinner', 'Medium', 'Italian', 430, 'http://localhost:5000/uploads/perfect_food_35.jpg', 195),
(36, 1, 'Classic American Cheeseburger with Fries', 'Juicy grilled beef patty topped with melted cheddar cheese, lettuce, tomato, pickles, and secret sauce on brioche.', '200g ground beef patty\n1 slice American cheddar cheese\n1 brioche burger bun\nLettuce, tomato, pickle slices\n1 tbsp burger sauce\nHandful crispy fries', '1. Shape beef into thick patty and season liberally with salt and pepper.\n2. Sear on cast iron skillet for 4 mins per side; melt cheddar slice on top.\n3. Toast brioche bun halves in butter.\n4. Spread burger sauce on bottom bun, add lettuce, tomato, cheesy patty, and pickles.\n5. Serve immediately with piping hot crispy fries!', 10, 10, 1, 'Lunch', 'Easy', 'American', 650, 'http://localhost:5000/uploads/perfect_food_36.jpg', 310),
(37, 1, 'Crispy Falafel Pita Wrap with Tahini', 'Golden crispy chickpea falafels tucked into warm pita bread with diced cucumber, tomatoes, and garlic tahini.', '6 falafels cooked\n2 warm pita pockets\n1/2 cup cucumber tomato salad\n1/4 cup pickled turnip or cabbage\n3 tbsp garlic tahini sauce', '1. Grind soaked chickpeas with parsley, garlic, cumin, and coriander; shape into balls.\n2. Deep fry falafels for 4 mins until deep brown and crispy.\n3. Warm pita pockets in skillet.\n4. Stuff pita pockets with falafels, cucumber tomato salad, and pickled turnip.\n5. Drizzle generously with garlic tahini sauce!', 20, 10, 2, 'Street Food', 'Medium', 'Mediterranean', 390, 'http://localhost:5000/uploads/perfect_food_37.jpg', 170),
(38, 3, 'Traditional Thai Tom Yum Goong Soup', 'Hot & sour Thai soup infused with lemongrass, kaffir lime leaves, galangal, jumbo shrimp, and straw mushrooms.', '300g jumbo shrimp\n4 cups chicken broth\n3 stalks lemongrass bruised\n4 kaffir lime leaves\n100g straw mushrooms\n2 tbsp Thai chili paste & lime juice', '1. Bring chicken broth to boil with lemongrass, galangal, and kaffir lime leaves.\n2. Add straw mushrooms and Thai chili paste; simmer for 5 mins.\n3. Add jumbo shrimp and cook for 3 mins until pink.\n4. Turn off heat and stir in fresh lime juice and fish sauce.\n5. Garnish with fresh cilantro and sliced red chilies!', 15, 15, 3, 'Soup', 'Medium', 'Thai', 210, 'http://localhost:5000/uploads/perfect_food_38.jpg', 185),
(39, 3, 'Authentic Japanese Salmon Teriyaki Bowl', 'Pan-seared salmon fillet glazed with sweet soy teriyaki sauce over steamed rice and steamed broccoli.', '2 salmon fillets\n3 tbsp soy sauce & mirin\n1 tbsp sugar & sake\n1 cup steamed Japanese rice\n1 cup steamed broccoli & sesame seeds', '1. Combine soy sauce, mirin, sugar, and sake in pan; simmer until glaze thickens.\n2. Sear salmon fillets skin-side down in skillet for 4 mins per side.\n3. Pour sweet teriyaki glaze over salmon, basting until glossy.\n4. Serve salmon over steamed rice with broccoli.\n5. Garnish with toasted sesame seeds and chopped scallions!', 10, 12, 2, 'Lunch', 'Easy', 'Japanese', 490, 'http://localhost:5000/uploads/perfect_food_39.jpg', 205),
(40, 2, 'Fluffy Pancakes with Maple Syrup & Berries', 'Golden stack of buttermilk pancakes drizzled with pure Canadian maple syrup and fresh blueberries.', '1.5 cups flour\n1 tbsp baking powder\n1.25 cups buttermilk\n1 egg\n3 tbsp melted butter\nPure maple syrup & fresh berries', '1. Whisk flour, sugar, baking powder, buttermilk, egg, and melted butter into batter.\n2. Heat griddle over medium heat and grease with butter.\n3. Pour 1/4 cup batter for each pancake; cook until bubbles form on surface.\n4. Flip and cook for 1-2 mins until golden brown.\n5. Stack high, top with fresh berries and maple syrup!', 10, 15, 3, 'Breakfast', 'Easy', 'American', 380, 'http://localhost:5000/uploads/perfect_food_40.jpg', 270),
(41, 4, 'Fiery Andhra Style Chilli Chicken', 'Spicy South Indian dry chicken fry tossed with green chilies, curry leaves, and freshly ground black pepper.', '500g chicken boneless\n6 green chilies slit\n15 curry leaves\n1 tbsp ginger garlic paste\n1 tsp black pepper powder\n1 tbsp soy sauce & lemon juice', '1. Marinate chicken with ginger garlic paste, pepper, and cornstarch for 30 mins.\n2. Shallow fry chicken pieces until crispy and cooked through.\n3. In same pan, toss green chilies, curry leaves, and garlic in oil.\n4. Add fried chicken pieces, pepper powder, and soy sauce; toss on high flame for 2 mins.\n5. Finish with fresh lemon juice and cilantro!', 15, 20, 3, 'Dinner', 'Medium', 'South Indian', 420, 'http://localhost:5000/uploads/perfect_food_41.jpg', 215),
(42, 2, 'Creamy Avocado Lime Vegan Smoothie', 'Refreshing plant-based green smoothie blended with ripe avocado, spinach, lime juice, and coconut water.', '1 ripe avocado\n1 cup fresh spinach\n1 cup coconut water\n1 tbsp lime juice\n1 tbsp agave nectar\nIce cubes', '1. Scoop avocado flesh into high-speed blender.\n2. Add spinach, coconut water, lime juice, agave nectar, and ice.\n3. Blend on high speed for 60 seconds until silky smooth.\n4. Pour into chilled glass.\n5. Garnish with a lime wheel!', 5, 0, 1, 'Beverages', 'Easy', 'Global', 220, 'http://localhost:5000/uploads/perfect_food_42.jpg', 135),
(43, 4, 'Crispy Onion & Stuffed Mirchi Bajji', 'Traditional Indian street food favorite featuring stuffed green chilies and onions dipped in spiced gram flour batter and deep-fried until golden brown.', '8 large green chilies (Mirchi) or 3 sliced onions\n1.5 cups besan (gram flour)\n1 tsp ajwain (carom seeds)\n1/2 tsp turmeric & red chili powder\n1 pinch baking soda\nOil for deep frying', '1. Make a vertical slit in green chilies and stuff with tangy cumin-chaat masala mixture.\n2. Whisk besan, ajwain, turmeric, chili powder, and water into a smooth thick batter.\n3. Dip stuffed green chilies or sliced onions into batter until fully coated.\n4. Deep fry in hot oil for 4-5 mins until golden brown and crispy.\n5. Drain and serve hot with sweet tamarind and mint chutneys!', 15, 12, 4, 'Starter', 'Easy', 'Indian', 290, 'http://localhost:5000/uploads/bajji.png', 180),
(44, 4, 'Authentic Indian Kanda Poha', 'Traditional Maharashtrian & Central Indian breakfast made with flattened rice, crunchy peanuts, mustard seeds, curry leaves, and turmeric.', '2 cups thick poha (flattened rice)\n1 medium onion finely chopped\n1/4 cup raw peanuts\n1 tsp mustard seeds & green chilies\n10 curry leaves & 1/2 tsp turmeric\n2 tbsp oil & lemon juice', '1. Rinse poha in colander gently; drain and mix with turmeric, sugar, and salt.\n2. Heat oil in pan; fry peanuts until golden brown and crispy.\n3. Add mustard seeds, curry leaves, and green chilies; let crackle.\n4. Saute chopped onions until translucent.\n5. Stir in soaked poha, cover and steam on low heat for 3 mins. Serve warm topped with fresh coriander and lemon juice!', 10, 10, 2, 'Breakfast', 'Easy', 'Indian', 240, 'http://localhost:5000/uploads/perfect_food_44.jpg', 195),
(45, 4, 'Kerala Malabar Parotta with Veg Kurma', 'Multi-layered flaky, soft South Indian flatbread served with rich, coconut and spice-infused vegetable kurma gravy.', '2 cups all-purpose flour (maida)\n1 tsp sugar & 1/2 cup warm water\n4 tbsp oil or ghee\n1 cup mixed vegetables (carrots, peas, potatoes)\n1/2 cup fresh coconut paste with cashews & fennel seeds', '1. Knead flour, sugar, water, and oil into soft elastic dough; rest 2 hours.\n2. Roll thin, pleat accordion style, curl into spiral, roll again, and cook on hot tava with ghee until golden flaky layers separate.\n3. Sauté onions, spices, and coconut cashew paste for vegetable kurma; simmer vegetables for 20 mins.\n4. Crush hot parottas between palms to fluff up flaky layers and serve hot with kurma!', 30, 25, 4, 'Lunch', 'Medium', 'South Indian', 490, 'http://localhost:5000/uploads/perfect_food_45.jpg', 260),
(46, 3, 'Crispy Steamed Himalayan Veg Momos', 'Popular Tibetan & Nepali dumplings stuffed with finely minced vegetables, garlic, and ginger, served with fiery red chili chutney.', '2 cups all-purpose flour\n2 cups finely shredded cabbage & carrots\n1 tbsp minced ginger & garlic\n1 tbsp soy sauce & sesame oil\nFiery red chili garlic chutney', '1. Knead flour and water into smooth firm dough; rest 20 mins.\n2. Sauté shredded cabbage, carrots, ginger, garlic, and soy sauce briefly for filling.\n3. Roll thin small dough circles, add filling, pleat edges neatly to seal.\n4. Steam in momo steamer for 10-12 mins until skin turns translucent.\n5. Serve hot with spicy Himalayan red chili sauce!', 25, 12, 4, 'Snacks', 'Medium', 'Asian', 270, 'http://localhost:5000/uploads/perfect_food_46.jpg', 310),
(47, 3, 'Korean Spicy Fried Chicken (Yangnyeom)', 'Ultra-crispy double-fried chicken bites coated in a sticky, sweet, and spicy Korean Gochujang glaze.', '500g chicken bite-size pieces\n1/2 cup potato starch or cornstarch\n2 tbsp Gochujang (Korean chili paste)\n2 tbsp honey or brown sugar\n1 tbsp soy sauce & minced garlic\nOil for double frying', '1. Coat chicken pieces thoroughly in potato starch.\n2. Deep fry chicken at 330°F for 6 mins; remove and rest.\n3. Double fry chicken at 375°F for 3 mins until shatteringly crispy.\n4. Simmer Gochujang, honey, soy sauce, and garlic in pan until glossy sauce forms.\n5. Toss crispy fried chicken in glaze and garnish with toasted sesame seeds!', 20, 15, 3, 'Starter', 'Medium', 'Korean', 520, 'http://localhost:5000/uploads/perfect_food_47.jpg', 285),
(48, 2, 'Classic Royal Gulab Jamun with Rabri', 'Soft milk-solid (khoya) dumplings fried to golden brown and soaked in cardamom-saffron sugar syrup, served with creamy rabri.', '1 cup khoya (mawa) or milk powder\n2 tbsp all-purpose flour\n1 pinch baking soda\n1.5 cups sugar & 1.5 cups water\nCardamom pods, saffron & rose water\nGhee for deep frying', '1. Knead khoya, flour, and baking soda into smooth dough without cracks.\n2. Shape into smooth small round balls.\n3. Boil sugar and water with cardamom and saffron for 8 mins into warm syrup.\n4. Deep fry balls in warm ghee on low heat until deep golden brown.\n5. Soak in warm syrup for 2 hours and serve garnished with pistachios!', 20, 20, 4, 'Dessert', 'Medium', 'Indian', 380, 'http://localhost:5000/uploads/perfect_food_48.jpg', 340),
(49, 4, 'Creamy Dal Makhani with Butter Garlic Naan', 'Slow-cooked black lentils and kidney beans simmered overnight with butter, cream, and aromatic spices.', '1 cup whole black urad dal\n1/4 cup rajma (kidney beans)\n3 tbsp butter & 1/4 cup heavy cream\n1 cup tomato puree\n1 tbsp ginger garlic paste & garam masala', '1. Soak black dal and rajma overnight; pressure cook for 6-8 whistles until ultra soft.\n2. Sauté ginger garlic paste and tomato puree in butter until aromatic.\n3. Add cooked dal, water, and simmer on low flame for 45 mins while stirring and mashing.\n4. Finish with butter, heavy cream, and kasuri methi.\n5. Serve piping hot with charred butter garlic naan!', 20, 60, 4, 'Dinner', 'Medium', 'Indian', 450, 'http://localhost:5000/uploads/perfect_food_49.jpg', 290),
(50, 4, 'Traditional South Indian Filter Coffee', 'Aromatic brewing of dark roasted chicory coffee decoction frothing high with boiled full-fat milk and sugar.', '3 tbsp South Indian filter coffee powder\n1 cup boiling water\n1.5 cups full-fat milk boiled\n2 tsp sugar', '1. Add coffee powder to upper chamber of brass filter; pour boiling water and let decoction drip for 15 mins.\n2. Boil milk in separate saucepan.\n3. Add 2 tbsp strong decoction and sugar into brass dabarah cup.\n4. Pour boiling hot milk from height to form thick frothy foam.\n5. Serve piping hot in traditional brass davarah!', 5, 10, 2, 'Beverages', 'Easy', 'South Indian', 110, 'http://localhost:5000/uploads/perfect_food_50.jpg', 160),
(51, 1, 'Crispy French Garlic Butter Baguette', 'Warm French baguette slices brushed with garlic, parsley, and melted parmesan butter, baked until golden.', '1 French baguette loaf\n1/2 cup unsalted butter softened\n4 cloves garlic minced\n2 tbsp fresh parsley chopped\n1/4 cup shredded parmesan cheese', '1. Slice baguette into 1-inch thick diagonal slices without cutting completely through bottom.\n2. Mix softened butter, minced garlic, parsley, and parmesan cheese in bowl.\n3. Spread garlic butter generously between baguette slices.\n4. Wrap tightly in aluminum foil and bake at 400°F for 15 mins.\n5. Unwrap top and bake 5 mins more until crusty and golden brown!', 10, 15, 4, 'Starter', 'Easy', 'French', 280, 'http://localhost:5000/uploads/perfect_food_51.jpg', 175),
(52, 1, 'Fresh Caesar Salad with Grilled Chicken', 'Crisp romaine lettuce hearts tossed with creamy Caesar dressing, garlic croutons, and grilled chicken breast.', '2 romaine lettuce heads chopped\n1 chicken breast grilled & sliced\n1/2 cup garlic croutons\n1/4 cup shaved parmesan cheese\n1/3 cup creamy Caesar dressing', '1. Season chicken breast and grill for 6 mins per side until cooked; slice thinly.\n2. Chop fresh romaine lettuce into bite-size pieces and wash in cold water.\n3. Toss lettuce with creamy Caesar dressing in large salad bowl.\n4. Top with warm grilled chicken slices, crunchy croutons, and shaved parmesan.\n5. Serve immediately with fresh black pepper!', 15, 12, 2, 'Salad', 'Easy', 'American', 370, 'http://localhost:5000/uploads/perfect_food_52.jpg', 210),
(53, 2, 'Authentic Spanish Churros with Dark Chocolate', 'Golden crispy fried dough pastry dusted in cinnamon sugar, served with thick dip dark chocolate.', '1 cup water & 2 tbsp sugar\n2 tbsp butter & 1 cup flour\n1 tsp cinnamon powder mixed with 1/2 cup sugar\n100g dark chocolate & 1/2 cup heavy cream', '1. Boil water, butter, and sugar in saucepan; stir in flour until dough forms ball.\n2. Transfer dough to piping bag fitted with star tip.\n3. Pipe 4-inch strips into hot oil and fry for 4 mins until deep golden.\n4. Roll hot churros immediately in cinnamon sugar.\n5. Melt dark chocolate with heavy cream for rich dipping sauce!', 15, 15, 4, 'Dessert', 'Easy', 'Spanish', 410, 'http://localhost:5000/uploads/perfect_food_53.jpg', 230),
(54, 2, 'Creamy Spinach & Mushroom Quesadilla', 'Golden toasted flour tortillas stuffed with sautéed garlic spinach, mushrooms, and melted Monterey Jack cheese.', '2 large flour tortillas\n1 cup baby spinach sautéed\n1 cup mushrooms sliced & cooked\n1 cup Monterey Jack cheese shredded\nSalsa & sour cream for dipping', '1. Sauté mushrooms and spinach with minced garlic until soft.\n2. Place flour tortilla on hot skillet; sprinkle half cheese, spinach-mushroom filling, and top with remaining cheese.\n3. Fold tortilla in half or place second tortilla on top.\n4. Grill for 3 mins per side until tortilla is crispy golden and cheese is molten.\n5. Cut into triangles and serve warm with guacamole and salsa!', 10, 10, 2, 'Snacks', 'Easy', 'Mexican', 360, 'http://localhost:5000/uploads/perfect_food_54.jpg', 185),
(55, 4, 'Crispy Pani Puri (Golgappa) with Tangy Water', 'Iconic Indian street food featuring hollow crispy puri shells filled with spiced potatoes, chickpeas, boondi, and served with chilled tangy mint-tamarind water.', '30 hollow puri shells\n2 boiled potatoes cubed\n1/2 cup boiled black chickpeas\n1 cup fresh mint & 1/2 cup coriander\n2 green chilies\n1 tbsp tamarind pulp & 1 tsp chaat masala\nBoondi & chilled water', '1. Blend mint, coriander, green chilies, ginger, tamarind pulp, chaat masala, and rock salt with chilled water into tangy Pani Puri water.\n2. Mash boiled potatoes with black chickpeas, red chili, and cumin powder for stuffing.\n3. Gently crack open top of a crispy puri shell with thumb.\n4. Fill with potato-chickpea stuffing and pour chilled tangy mint water.\n5. Eat whole puri in one delicious bite!', 20, 10, 4, 'Street Food', 'Medium', 'Indian', 260, 'http://localhost:5000/uploads/panipuri.png', 320),
(56, 4, 'Authentic Delhi Chole Bhature', 'Classic Punjabi combination of dark, aromatic spicy chickpea gravy served with fluffy, deep-fried puffed bhatura bread, raw onion rings, and lemon wedges.', '2 cups kabuli chana (chickpeas)\n2 cups maida (flour)\n1/2 cup yogurt\n2 onions finely chopped\n2 tomatoes pureed\n2 tbsp Chole masala & tea bag for color\nWhole spices (bay leaf, cinnamon, cloves)\nOil for deep frying', '1. Pressure cook soaked chickpeas with tea bag and whole spices until soft.\n2. Knead maida, yogurt, sugar, and baking powder into soft bhatura dough; rest 2 hours.\n3. Prepare rich chole gravy with onions, tomato puree, and chole masala; simmer chickpeas for 25 mins.\n4. Roll bhatura dough into thick ovals and deep fry in hot oil until puffed and golden.\n5. Serve hot bhaturas alongside spicy chole, raw onion rings, and lemon wedges!', 30, 30, 4, 'Breakfast', 'Medium', 'Indian', 590, 'http://localhost:5000/uploads/chole_bhature.jpg', 380),
(57, 4, 'Spicy Hyderabadi Haleem', 'Rich Nizam slow-cooked stew made of wheat, barley, minced meat, lentils, and aromatic spices pounded into a velvety paste.', '500g mutton or chicken boneless\n1 cup broken wheat (dalia)\n1/4 cup chana dal & urad dal\n1/2 cup ghee & fried onions\n1 tbsp ginger garlic paste & haleem masala\nLemon wedges & mint leaves', '1. Soak broken wheat and lentils for 3 hours.\n2. Cook meat with spices, ginger garlic paste, and lentils in pressure cooker until ultra tender.\n3. Mash meat and wheat mixture thoroughly using wooden mallet until smooth stretchable texture.\n4. Drizzle generous hot ghee and simmer for 20 mins.\n5. Serve garnished with fried crispy onions, cashew nuts, mint, and lemon juice!', 40, 60, 4, 'Dinner', 'Hard', 'South Indian', 540, 'http://localhost:5000/uploads/perfect_food_57.jpg', 290),
(58, 4, 'Spicy South Indian Gobi 65 (Starter)', 'Crispy cauliflower florets marinated in South Indian spices, curry leaves, and rice flour, deep-fried to golden perfection and garnished with red onion rings.', '1 head cauliflower cut in florets\n1/2 cup rice flour\n1/4 cup cornstarch\n1 tbsp ginger garlic paste\n1 tbsp Kashmiri red chili powder\n15 curry leaves & 3 green chilies slit\nRed onion rings & oil for frying', '1. Blanch cauliflower florets in boiling salted water for 3 mins and drain.\n2. Mix rice flour, cornstarch, ginger garlic paste, chili powder, and water into thick batter.\n3. Coat blanched cauliflower florets thoroughly in batter.\n4. Deep fry florets in hot oil for 5-6 mins until deep red, crispy, and crunchy.\n5. Fry curry leaves and slit green chilies in oil; toss over hot Gobi 65 with onion rings before serving!', 15, 15, 4, 'Starter', 'Easy', 'South Indian', 310, 'http://localhost:5000/uploads/gobi65.png', 340),
(59, 4, 'Authentic Punjabi Crispy Potato Samosa', 'Golden triangular pastry crust filled with spiced potatoes, green peas, and cashews, served with mint and tamarind chutneys.', '2 cups all-purpose flour (maida)\n4 tbsp ghee or oil\n4 boiled potatoes mashed\n1/2 cup green peas\n1 tbsp ginger minced & green chilies\n1 tsp cumin, coriander, and garam masala\nOil for deep frying', '1. Knead flour, ghee, salt, and carom seeds into a stiff dough; rest 30 mins.\n2. Sauté ginger, chilies, peas, mashed potatoes, and spices for filling.\n3. Roll dough into oval, cut in half, form cone, fill with potato masala, and seal edges tightly.\n4. Fry samosas on low-medium heat for 15-20 mins until deep golden and extra crispy.\n5. Serve hot with sweet tamarind chutney and spicy green chutney!', 25, 20, 4, 'Starter', 'Medium', 'Indian', 320, 'http://localhost:5000/uploads/samosa.png', 410),
(60, 2, 'Royal Mango Rasamalai with Pistachios', 'Soft cottage cheese discs soaked in saffron-infused mango rabri milk, topped with silver leaf and sliced pistachios.', '10 rasgulla discs squeezed\n2 cups full-fat milk\n1 cup Alphonso mango puree\n1/4 tsp cardamom powder & saffron\n2 tbsp pistachios & almonds', '1. Simmer milk until reduced by half.\n2. Add sugar, cardamom, saffron, and Alphonso mango puree; cool.\n3. Squeeze syrup out of soft rasgulla discs gently.\n4. Submerge discs into chilled mango milk.\n5. Garnish with slivered pistachios and chill for 4 hours before serving!', 15, 20, 4, 'Dessert', 'Medium', 'Indian', 290, 'http://localhost:5000/uploads/perfect_food_60.jpg', 210);
