INSERT INTO comments (id, recipe_id, user_id, comment) VALUES
(1, 4, 1, 'The dosa was super crispy! The potato masala ratio is spot on.'),
(2, 5, 2, 'Best biryani recipe I have made at home. Saffron aroma was incredible!'),
